# %% [markdown]
# ## Shared temporal-window protocol
# PCA and CNN must receive the same observations.
# Each neural sample is a centered window with shape:
#
# ```text
# window size × number of neurons
# ```
#
# PCA flattens each window into one vector.
#
# The CNN keeps the temporal and neural axes separate.
#
# The corresponding benchmark target is the mean ``Z_task`` state inside the
# same temporal window.


# %%
# =========================
# EXPERIMENT CONFIGURATION
# =========================

RANDOM_STATE = 24

# Temporal windows provide each model with short local neural histories instead of isolated time bins.
WINDOW_SIZE = 10
STRIDE = 1
TIME_MODE = "absolute"
WINDOW_PADDING = "center"
PAD_VALUE = 0.0

# PCA and CNN have different output dimensionalities by design.
#
# PCA retains five components because the task benchmark has five coordinates
PCA_N_COMPONENTS = 5

# Three dimensions remain the default. An environment override supports
# controlled output-dimensionality ablations without editing this file.
CNN_EMBEDDING_DIM = requested_cnn_dim

# Z_task contains five coordinates:
#
# 0. Position X
# 1. Position Y
# 2. Movement progress
# 3. Velocity
# 4. Context
#
# A five-dimensional CNN is evaluated against the complete task latent. The
# default 3D CNN is evaluated against position and movement progress.
CNN_ZTASK_DIMS = (
    tuple(range(K))
    if CNN_EMBEDDING_DIM == K
    else (0, 1, 2)
)

# PCA produces exactly three figures per subject:
#
# 1. a readable PC1-PC2 scatter;
# 2. one mean trajectory per condition in PC1-PC2;
# 3. cumulative explained variance.
#
# Only the scatter is limited to 500 displayed windows. PCA fitting and all
# metrics still use the complete available dataset.
PCA_SCATTER_MAX_POINTS = 500
PCA_PLOT_DIMS = (0, 1)

# RSA (Representational Similarity Analysis.) 
# uses pairwise distances and can be expensive on every window.
METRIC_MAX_SAMPLES = 2500
BATCH_SIZE = 256
CNN_EPOCHS = requested_cnn_epochs
LEARNING_RATE = 1e-3
WEIGHT_DECAY = 1e-4

TEMPERATURE = 0.2
SIMILARITY_TAU = 0.5
TIME_WEIGHT = 0.5
LABEL_WEIGHT = 0.5

DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

if PCA_N_COMPONENTS != K:
    raise ValueError(
        "For full PCA-vs-Z_task recovery, PCA_N_COMPONENTS must equal K. "
        f"Current values: PCA_N_COMPONENTS={PCA_N_COMPONENTS}, K={K}."
    )

if len(CNN_ZTASK_DIMS) != CNN_EMBEDDING_DIM:
    raise ValueError(
        "CNN_ZTASK_DIMS must contain one target dimension for each CNN "
        "embedding dimension."
    )

if max(CNN_ZTASK_DIMS) >= K:
    raise ValueError(
        f"CNN_ZTASK_DIMS={CNN_ZTASK_DIMS} is incompatible with K={K}."
    )


# %%
# =========================
# REPRODUCIBILITY
# =========================

def set_seed(seed: int) -> None:
    """Set Python, NumPy and PyTorch random seeds."""

    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)

    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)


set_seed(RANDOM_STATE)

print("Device:", DEVICE)
print("Window size:", WINDOW_SIZE)
print("PCA components:", PCA_N_COMPONENTS)
print("CNN dimensions:", CNN_EMBEDDING_DIM)
print("CNN Z_task dimensions:", CNN_ZTASK_DIMS)


# %%
# =========================
# WINDOW DATASET
# =========================

def make_window_dataset(
    X: np.ndarray,
    Z_task_source: np.ndarray,
    labels: np.ndarray,
) -> tuple[TemporalWindowDataset, np.ndarray]:
    """
    Build the same temporal windows for PCA, CNN and Z_task.

    PCA later flattens each neural window. CNN keeps the two-dimensional
    window structure. The target associated with each observation is the mean
    Z_task state inside the corresponding latent window.
    """

    X = np.asarray(X)
    Z_task_source = np.asarray(Z_task_source)
    labels = np.asarray(labels)

    X_2d = X.reshape(-1, X.shape[-1])
    Z_task_2d = Z_task_source.reshape(-1, K)

    X_windows, time_id, global_time_id, trial_id, labels_windows = build_windows(
        X_2d,
        WINDOW_SIZE,
        STRIDE,
        labels=labels,
        trial_len=TRIAL_LENGTH,
        time_mode=TIME_MODE,
        padding=WINDOW_PADDING,
        pad_value=PAD_VALUE,
    )

    Z_task_windows, _, _, _, _ = build_windows(
        Z_task_2d,
        WINDOW_SIZE,
        STRIDE,
        labels=labels,
        trial_len=TRIAL_LENGTH,
        time_mode=TIME_MODE,
        padding=WINDOW_PADDING,
        pad_value=PAD_VALUE,
    )

    dataset = TemporalWindowDataset(
        X_windows,
        time_id,
        global_time_id,
        trial_id,
        labels_windows,
    )

    Z_task_target = Z_task_windows.mean(axis=1)

    if len(dataset) != len(Z_task_target):
        raise RuntimeError(
            "Neural windows and Z_task targets are not aligned."
        )

    return dataset, Z_task_target


def extract_window_metadata(
    dataset: TemporalWindowDataset,
) -> dict[str, np.ndarray]:
    """Extract ordered metadata and reconstruct within-trial window position."""

    labels = dataset.labels_windows.numpy()
    trial_id = dataset.trial_id.numpy()
    time_id = dataset.time_id.numpy()
    global_time_id = dataset.global_time_id.numpy()

    within_trial_time = np.empty(len(dataset), dtype=int)

    for trial in np.unique(trial_id):
        trial_indices = np.flatnonzero(trial_id == trial)
        within_trial_time[trial_indices] = np.arange(len(trial_indices))

    return {
        "labels": labels,
        "trial_id": trial_id,
        "time_id": time_id,
        "global_time_id": global_time_id,
        "within_trial_time": within_trial_time,
    }


def sample_indices(
    n_observations: int,
    max_samples: int,
    seed: int,
) -> np.ndarray:
    """Return all observations or a reproducible ordered subset."""

    if n_observations <= max_samples:
        return np.arange(n_observations)

    rng = np.random.default_rng(seed)

    return np.sort(
        rng.choice(
            n_observations,
            size=max_samples,
            replace=False,
        )
    )


def evaluate_latent_recovery_sampled(
    embedding: np.ndarray,
    latent: np.ndarray,
    max_samples: int,
    seed: int,
) -> dict:
    """
    Evaluate latent recovery on a reproducible subset when necessary.

    RSA requires pairwise distances between observations. Sampling keeps memory and runtime manageable while preserving a reproducible evaluation.
    """

    embedding = np.asarray(embedding)
    latent = np.asarray(latent)

    if embedding.shape[0] != latent.shape[0]:
        raise ValueError(
            "Embedding and latent target must contain the same observations."
        )

    indices = sample_indices(
        len(embedding),
        max_samples,
        seed,
    )

    return evaluate_latent_recovery(
        embedding[indices],
        latent[indices],
    )


def plot_condition_average_trajectories_2d(
    embedding: np.ndarray,
    labels: np.ndarray,
    within_trial_time: np.ndarray,
    output_path: Path,
    title: str,
    dims: tuple[int, int] = (0, 1),
) -> None:
    """
    Plot one mean PCA trajectory for each condition.

    Observations are averaged across trials at the same within-trial window
    position. This prevents the unreadable plot obtained by connecting every
    individual trial.
    """

    embedding = np.asarray(embedding)
    labels = np.asarray(labels)
    within_trial_time = np.asarray(within_trial_time)

    fig, ax = plt.subplots(figsize=(7, 7))

    for label in np.unique(labels):
        condition_mask = labels == label
        time_values = np.unique(
            within_trial_time[condition_mask]
        )

        trajectory = np.asarray([
            embedding[
                condition_mask & (within_trial_time == time_value)
            ][:, dims].mean(axis=0)
            for time_value in time_values
        ])

        ax.plot(
            trajectory[:, 0],
            trajectory[:, 1],
            linewidth=1.8,
            label=f"cond {label}",
        )

        ax.scatter(
            trajectory[0, 0],
            trajectory[0, 1],
            marker="x",
            s=45,
        )

        ax.scatter(
            trajectory[-1, 0],
            trajectory[-1, 1],
            marker="o",
            s=25,
        )

    ax.set_xlabel(f"PC{dims[0] + 1}")
    ax.set_ylabel(f"PC{dims[1] + 1}")
    ax.set_title(title)
    ax.legend(title="Condition")
    ax.set_aspect("equal", adjustable="datalim")
    fig.tight_layout()
    fig.savefig(output_path, dpi=160)
    plt.show()
    plt.close(fig)


# %%
# =========================
# PREPARE SUBJECT DATA
# =========================

subject_windows = {}

for subject_name, subject_data in subjects.items():
    dataset, Z_task_target = make_window_dataset(
        X=np.asarray(subject_data["X"]),
        Z_task_source=Z_task,
        labels=cond,
    )

    metadata = extract_window_metadata(dataset)

    subject_windows[subject_name] = {
        "dataset": dataset,
        "Z_task_target": Z_task_target,
        "metadata": metadata,
    }

    print(
        f"{subject_name}: {len(dataset)} windows, "
        f"window tensor shape={tuple(dataset.X_windows.shape)}"
    )


# %% [markdown]
# ## PCA baseline
#
# PCA uses the temporal neural windows created above:
#
#     dataset.X_windows -> flatten each window -> PCA
#
# Five components are retained and all five are used for recovery evaluation.
# Only the scatter plot is reduced to 500 displayed points.
#
# Exactly three PCA figures are generated per subject:
#
# 1. PC1-PC2 scatter;
# 2. PC1-PC2 condition-averaged trajectories;
# 3. cumulative explained variance.


# %%
# =========================
# FIT PCA
# =========================

pca_results = {}

for subject_name, prepared in subject_windows.items():
    dataset = prepared["dataset"]
    metadata = prepared["metadata"]

    X_flat_windows = (
        dataset.X_windows
        .numpy()
        .reshape(len(dataset), -1)
    )

    pca = PCA(
        n_components=PCA_N_COMPONENTS,
        svd_solver="randomized",
        random_state=RANDOM_STATE,
    )

    pca_embedding = pca.fit_transform(X_flat_windows)

    task_metrics = evaluate_latent_recovery_sampled(
        embedding=pca_embedding,
        latent=prepared["Z_task_target"],
        max_samples=METRIC_MAX_SAMPLES,
        seed=RANDOM_STATE,
    )

    pca_model_path = models_dir / f"{subject_name}_pca.pkl"

    with open(pca_model_path, "wb") as file:
        pickle.dump(pca, file)

    cumulative_variance = np.cumsum(
        pca.explained_variance_ratio_
    )

    pca_results[subject_name] = {
        "model_path": str(pca_model_path),
        "embedding": pca_embedding,
        "explained_variance_ratio": pca.explained_variance_ratio_,
        "cumulative_explained_variance": cumulative_variance,
        "metrics": {
            "Z_task_full": task_metrics,
        },
    }

    print(f"\n{subject_name} — PCA")
    print("Flattened input shape:", X_flat_windows.shape)
    print("PCA embedding shape:", pca_embedding.shape)
    print("Explained variance ratio:", pca.explained_variance_ratio_)
    print("Cumulative explained variance:", cumulative_variance)
    print("Recovery vs full Z_task:", task_metrics)

    # Plot 1/3: at most 500 points are displayed.
    plot_indices = sample_indices(
        n_observations=len(pca_embedding),
        max_samples=PCA_SCATTER_MAX_POINTS,
        seed=RANDOM_STATE,
    )

    plot_embedding_2d(
        embedding=pca_embedding[plot_indices],
        labels=metadata["labels"][plot_indices],
        output_folder=figures_dir,
        name=f"{subject_name}_pca_pc1_pc2_scatter.html",
        title=(
            f"{subject_name} — PCA PC1-PC2 "
            f"({len(plot_indices)} displayed windows)"
        ),
        dims=PCA_PLOT_DIMS,
        show=True,
    )

    # Plot 2/3: one averaged trajectory for every condition.
    plot_condition_average_trajectories_2d(
        embedding=pca_embedding,
        labels=metadata["labels"],
        within_trial_time=metadata["within_trial_time"],
        output_path=(
            figures_dir
            / f"{subject_name}_pca_pc1_pc2_condition_trajectories.png"
        ),
        title=(
            f"{subject_name} — PCA PC1-PC2 "
            "condition-averaged trajectories"
        ),
        dims=PCA_PLOT_DIMS,
    )

    # Plot 3/3: cumulative explained variance in percentage units.
    component_numbers = np.arange(
        1,
        PCA_N_COMPONENTS + 1,
    )

    fig, ax = plt.subplots(figsize=(7, 4))
    ax.plot(
        component_numbers,
        100.0 * cumulative_variance,
        marker="o",
    )
    ax.set_xlabel("Number of PCA components")
    ax.set_ylabel("Cumulative explained variance (%)")
    ax.set_title(f"{subject_name} — cumulative PCA variance")
    ax.set_xticks(component_numbers)
    ax.set_ylim(
        0,
        max(
            1.0,
            105.0 * float(cumulative_variance[-1]),
        ),
    )
    fig.tight_layout()
    fig.savefig(
        figures_dir / f"{subject_name}_pca_explained_variance.png",
        dpi=160,
    )
    plt.show()
    plt.close(fig)


# %% [markdown]
# ## Temporal CNN
#
# The CNN receives the same temporal windows without flattening them.
# It produces a three-dimensional embedding.
#
# Training uses the structured soft contrastive objective already implemented
# in NeuroBridge. Z_task is used only after training for evaluation.
#
# Exactly three CNN figures are generated per subject:
#
# 1. three-dimensional embedding by condition;
# 2. three-dimensional trajectories grouped by condition;
# 3. training loss.


# %%
# =========================
# CNN FACTORY
# =========================

def make_cnn_encoder(
    dataset: TemporalWindowDataset,
) -> TemporalCNNEncoder:
    """Create the existing NeuroBridge temporal CNN."""

    sample_window = dataset[0]["x"]
    window_size, n_features = sample_window.shape

    if window_size != WINDOW_SIZE:
        raise RuntimeError(
            f"Dataset window size is {window_size}, "
            f"expected {WINDOW_SIZE}."
        )

    return TemporalCNNEncoder(
        n_features=n_features,
        embedding_dim=CNN_EMBEDDING_DIM,
        hidden_dim=64,
        n_layers=3,
    )


# %%
# =========================
# CNN TRAINING
# =========================

def train_cnn(
    dataset: TemporalWindowDataset,
) -> tuple[TemporalCNNEncoder, np.ndarray, list[float]]:
    """
    Train one CNN and return embeddings in the original dataset order.

    Training minibatches are shuffled. Final encoding is not shuffled, so
    embeddings remain aligned with Z_task and all window metadata.
    """

    training_loader = DataLoader(
        dataset,
        batch_size=BATCH_SIZE,
        shuffle=True,
        drop_last=True,
    )

    model = make_cnn_encoder(dataset).to(DEVICE)

    optimizer = torch.optim.AdamW(
        model.parameters(),
        lr=LEARNING_RATE,
        weight_decay=WEIGHT_DECAY,
    )

    loss_fn = lambda embedding, similarity: soft_contrastive_loss(
        embedding,
        similarity,
        temperature=TEMPERATURE,
    )

    similarity_builder = lambda batch: batch_structured_similarity(
        batch,
        time_weight=TIME_WEIGHT,
        label_weight=LABEL_WEIGHT,
        tau=SIMILARITY_TAU,
        num_labels=N_CONDITIONS,
    )

    losses = []

    for epoch in range(CNN_EPOCHS):
        epoch_loss = train_epoch(
            model,
            training_loader,
            optimizer,
            loss_fn,
            device=DEVICE,
            similarity_builder=similarity_builder,
            batch_loss=False,
        )

        losses.append(float(epoch_loss))

        print(
            f"Epoch {epoch + 1:03d}/{CNN_EPOCHS}: "
            f"loss={float(epoch_loss):.6f}"
        )

    ordered_loader = DataLoader(
        dataset,
        batch_size=BATCH_SIZE,
        shuffle=False,
        drop_last=False,
    )

    encoded_windows, _ = encode_windows(
        model,
        ordered_loader,
        device=DEVICE,
    )

    embedding = encoded_windows.numpy()

    expected_shape = (
        len(dataset),
        CNN_EMBEDDING_DIM,
    )

    if embedding.shape != expected_shape:
        raise RuntimeError(
            f"Unexpected CNN embedding shape {embedding.shape}; "
            f"expected {expected_shape}."
        )

    return model, embedding, losses


# %%
# =========================
# TRAIN CNN
# =========================

cnn_results = {}

for subject_name, prepared in subject_windows.items():
    print(f"\nTraining CNN for {subject_name}")

    set_seed(RANDOM_STATE)

    model, embedding, losses = train_cnn(
        prepared["dataset"]
    )

    # Procrustes requires equal dimensionality. The CNN is therefore compared
    # with the explicitly selected three coordinates of Z_task.
    cnn_Z_task_target = prepared["Z_task_target"][
        :,
        CNN_ZTASK_DIMS,
    ]

    task_metrics = evaluate_latent_recovery_sampled(
        embedding=embedding,
        latent=cnn_Z_task_target,
        max_samples=METRIC_MAX_SAMPLES,
        seed=RANDOM_STATE,
    )

    cnn_model_path = models_dir / f"{subject_name}_cnn_state.pt"

    torch.save(
        {
            "model_state_dict": model.state_dict(),
            "model_class": "TemporalCNNEncoder",
            "n_features": int(
                prepared["dataset"][0]["x"].shape[1]
            ),
            "embedding_dim": CNN_EMBEDDING_DIM,
            "hidden_dim": 64,
            "n_layers": 3,
        },
        cnn_model_path,
    )

    cnn_results[subject_name] = {
        "model_path": str(cnn_model_path),
        "embedding": embedding,
        "losses": losses,
        "Z_task_dims": CNN_ZTASK_DIMS,
        "metrics": {
            "Z_task_selected": task_metrics,
        },
    }

    print(f"\n{subject_name} — CNN")
    print("CNN embedding shape:", embedding.shape)
    print(
        f"Recovery vs Z_task dimensions {CNN_ZTASK_DIMS}:",
        task_metrics,
    )

    metadata = prepared["metadata"]

    # Embeddings above three dimensions are projected only for plotting.
    # Training, saved outputs, and recovery metrics retain all dimensions.
    embedding_for_plot = (
        embedding
        if CNN_EMBEDDING_DIM == 3
        else PCA(
            n_components=3,
            random_state=RANDOM_STATE,
        ).fit_transform(embedding)
    )

    # Plot 1/3: complete three-dimensional embedding.
    plot_embedding_sphere(
        embedding_for_plot,
        metadata["labels"],
        figures_dir,
        f"{subject_name}_cnn_sphere_scatter.html",
        title=f"{subject_name} — CNN 3D embedding by condition",
        normalize=CNN_EMBEDDING_DIM == 3,
        show=CNN_EMBEDDING_DIM == 3,
    )

    # Plot 2/3: three-dimensional trajectories grouped by condition.
    plot_condition_trajectories_sphere(
        embedding_for_plot,
        metadata["labels"],
        metadata["trial_id"],
        metadata["time_id"],
        figures_dir,
        f"{subject_name}_cnn_sphere_condition_trajectories.html",
        title=f"{subject_name} — CNN 3D condition-averaged trajectories",
        normalize=CNN_EMBEDDING_DIM == 3,
        show=CNN_EMBEDDING_DIM == 3,
    )

    if CNN_EMBEDDING_DIM > 3:
        plot_condition_trajectories_2d(
            embedding_for_plot,
            metadata["labels"],
            metadata["trial_id"],
            metadata["time_id"],
            figures_dir,
            f"{subject_name}_cnn_{CNN_EMBEDDING_DIM}d_pca_visualization_2d.html",
            title=(
                f"{subject_name} - CNN {CNN_EMBEDDING_DIM}D output, "
                "PCA visualization in 2D"
            ),
            dims=(0, 1),
            show=False,
        )

    # Plot 3/3: optimization history.
    fig, ax = plt.subplots(figsize=(7, 4))
    ax.plot(
        np.arange(1, len(losses) + 1),
        losses,
    )
    ax.set_xlabel("Epoch")
    ax.set_ylabel("Training loss")
    ax.set_title(f"{subject_name} — CNN training loss")
    fig.tight_layout()
    fig.savefig(
        figures_dir / f"{subject_name}_cnn_training_loss.png",
        dpi=160,
    )
    plt.show()
    plt.close(fig)

    model.to("cpu")


# %%
# =========================
# SAVE RESULTS
# =========================

results = {
    "simulation_path": str(simulation_path),
    "output_root": str(output_root),
    "experiment_config": {
        "random_state": RANDOM_STATE,
        "window_size": WINDOW_SIZE,
        "stride": STRIDE,
        "time_mode": TIME_MODE,
        "window_padding": WINDOW_PADDING,
        "pad_value": PAD_VALUE,
        "pca_n_components": PCA_N_COMPONENTS,
        "pca_scatter_max_points": PCA_SCATTER_MAX_POINTS,
        "cnn_embedding_dim": CNN_EMBEDDING_DIM,
        "cnn_Z_task_dims": CNN_ZTASK_DIMS,
        "metric_max_samples": METRIC_MAX_SAMPLES,
        "batch_size": BATCH_SIZE,
        "cnn_epochs": CNN_EPOCHS,
        "learning_rate": LEARNING_RATE,
        "weight_decay": WEIGHT_DECAY,
        "temperature": TEMPERATURE,
        "similarity_tau": SIMILARITY_TAU,
        "time_weight": TIME_WEIGHT,
        "label_weight": LABEL_WEIGHT,
        "device_used": DEVICE,
        "evaluation_target": "Z_task",
        "evaluation_mode": "windowed_full_data_latent_recovery",
    },
    "task_config": task_config,
    "subject_metadata": {
        subject_name: subject_data["config"]
        for subject_name, subject_data in subjects.items()
    },
    "window_data": {
        subject_name: {
            "metadata": prepared["metadata"],
            "Z_task_target": prepared["Z_task_target"],
        }
        for subject_name, prepared in subject_windows.items()
    },
    "pca_results": pca_results,
    "cnn_results": cnn_results,
}

with open(results_path, "wb") as file:
    pickle.dump(results, file)

